static void hurt_sound()
{
  T_NUMERIC r = rnd(1);
  if (r>0.75)
    {
      sound_play("hurt_1");
    }
  else if (r>0.5)
    {
      sound_play("hurt_2");
    }
  
}

static T_INT load_game(int slot)
{
  char gsn[100];
  sprintf(gsn,"gamesave.%d",slot);
    FILE *f = fopen(gsn,"rb");
    if (f != 0)
    {
      fread(&gs,sizeof(gs),1,f);
      fread(cpu_get_mem(),0x9800,1,f);
      fclose(f);
      
    }
    return (f != 0);
}
static T_INT save_game(int slot)
{
  char gsn[100];
  sprintf(gsn,"gamesave.%d",slot);
    FILE *f = fopen(gsn,"wb");
    if (f != 0)
    {
      fwrite(&gs,sizeof(gs),1,f);
      fwrite(cpu_get_mem(),0x9800,1,f);     
      fclose(f);
    }
    return (f != 0);

}

